# Python function to compute standard total revenue for multiple items
# Each item is a dict: {'price': float, 'quantity': int, 'discount': float (optional, fraction)}

def compute_total_revenue(items):
    """Compute total revenue as sum(price * quantity * (1 - discount)).

    Args:
        items (list of dict): Each dict must have 'price' and 'quantity'; may have 'discount' (0<=d<1).

    Returns:
        float: total revenue rounded to 2 decimal places.
    """
    if not isinstance(items, (list, tuple)):
        raise TypeError("items must be a list or tuple of item dicts")

    total = 0.0
    for i, item in enumerate(items):
        if not isinstance(item, dict):
            raise TypeError(f"item at index {i} is not a dict")
        try:
            price = float(item['price'])
            quantity = float(item['quantity'])
        except KeyError as e:
            raise KeyError(f"missing required key {e} in item at index {i}")
        discount = float(item.get('discount', 0.0))
        if not (0 <= discount < 1):
            raise ValueError(f"discount for item at index {i} must be in [0, 1)")
        total += price * quantity * (1 - discount)

    return round(total, 2)


# Example usage / simple test
if __name__ == '__main__':
    sample_items = [
        {'price': 10.0, 'quantity': 3},
        {'price': 5.5, 'quantity': 2, 'discount': 0.1},
        {'price': 100, 'quantity': 1, 'discount': 0.25}
    ]
    print("Total revenue:", compute_total_revenue(sample_items))

